#!/bin/sh
set -eu
root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
temporary=$(mktemp -d "${TMPDIR:-/tmp}/cyberguard-secrets.XXXXXX")
directory=$temporary/secrets
cleanup() {
    # Only files generated by this test in its private temporary directory.
    if [ -d "$directory" ]; then rm -f -- "$directory"/*; rmdir -- "$directory"; fi
    rmdir -- "$temporary"
}
trap cleanup EXIT
trap 'exit 1' HUP INT TERM
export DOCKER_SECRETS_DIR=$directory DOCKER_IDENTITY_PORT=15433 DOCKER_INCIDENT_PORT=15434
sh "$root/docker/create-secrets.sh" > /dev/null
test "$(stat -c %a "$directory")" = 700
test "$(find "$directory" -type f | wc -l)" = 18
test -z "$(find "$directory" -type f ! -perm 0640 -print)"
for database in identity incidents; do
    for kind in admin migration runtime; do
        grep -Eq '^[0-9a-f]{64}$' "$directory/${database}_${kind}_password"
    done
    for kind in runtime migration; do
        password=$(cat "$directory/${database}_${kind}_password")
        grep -Fq ":$password@" "$directory/${database}_${kind}_url"
        grep -Fq ":$password@" "$directory/${database}_${kind}_host_url"
    done
done
test "$(cat "$directory"/*_password | sort -u | wc -l)" = 10
grep -Fq '@127.0.0.1:15433/' "$directory/identity_runtime_host_url"
grep -Fq '@127.0.0.1:15434/' "$directory/incidents_runtime_host_url"
before=$(sha256sum "$directory"/*)
if sh "$root/docker/create-secrets.sh" > /dev/null 2>&1; then
    echo 'Secret provisioning must refuse existing directories' >&2
    exit 1
fi
test "$before" = "$(sha256sum "$directory"/*)"
echo 'Secret generation, permissions, URL consistency and overwrite protection passed.'
